    background: #f7fafc;

    color: #1a202c;

    font-weight: 600;

    font-size: 13px;

    text-transform: uppercase;

    letter-spacing: 0.5px;

    padding: 14px 12px;

    text-align: left;

    border-bottom: 2px solid #e2e8f0;

