<th style="width: 50%">Firm Name</th>
<th style="width: 30%">Last Modified Date</th>
</tr>
</thead>
<tbody>

          {{$json.firmTableRows}}
</tbody>
</table>
</div>
<!-- INDIVIDUAL DISCLOSURES SECTION -->
<div class="update-badge">
<p>
<span>⚠️</span>
<strong>{{ $json.individualTotalCount }} individuals have updated disclosures</strong>
</p>
</div>
<div class="data-section">
<h3>👥 Individuals with Updated Disclosures</h3>
<table class="individual-table">
<thead>
<tr>
<th style="width: 15%">Individual ID</th>
<th style="width: 25%">Individual Name</th>
<th style="width: 15%">Firm ID</th>
<th style="width: 25%">Firm Name</th>
<th style="width: 20%">Last Modified Date</th>
</tr>
</thead>
<tbody>

          {{$json.individualTableRows}}
</tbody>
</table>
</div>
</div>
<div class="footer">
<div class="signature">
<p>Best regards,</p>
<p><strong>Ahmed Shafique</strong></p>
