const items = $input.all();

// Escape HTML function

function escapeHtml(str) {

  if (str === null || str === undefined) return '';

  const strValue = String(str);

  return strValue

    .replace(/&/g, '&amp;')

    .replace(/</g, '&lt;')

    .replace(/>/g, '&gt;')

    .replace(/"/g, '&quot;')

    .replace(/'/g, '&#39;');

}

// Format date for display

function formatDate(dateString) {

  if (!dateString) return 'N/A';

  const date = new Date(dateString);

  if (isNaN(date.getTime())) return dateString;

  return date.toLocaleDateString('en-US', {

    year: 'numeric',

    month: 'short',

    day: 'numeric'

  });

}

// Process Individual Data

function processIndividuals(individualArray) {

  if (!individualArray || individualArray.length === 0) {

    return {

      changedCount: 0,

      totalCount: 0,

      tableRows: '<tr><td colspan="5" style="text-align: center; padding: 40px; color: #94a3b8;">✅ No individuals with updated disclosures at this time</td</tr>'

    };

  }

  const matchedItems = [];

  for (const item of individualArray) {

    const individualId = item.ind_source_id || 'N/A';

    // Handle empty individual_name - show as "N/A"

    let individualName = item.individual_name || '';

    if (!individualName || individualName.trim() === '') {

      individualName = 'N/A';

    }

    const firmId = item.employee_firm_id || 'N/A';

    const firmName = item.employee_firm_name || 'Unknown Firm';

    const url = item.url || '';

    const fileModified = item.file_last_modified_date;

    if (!fileModified) continue;

    if (!url || url.trim() === '') continue;

    matchedItems.push({

      individualId: individualId,

      individualName: individualName,

      firmId: firmId,

      firmName: firmName,

      url: url,

      lastModifiedDate: formatDate(fileModified)

    });

  }

  const totalChanged = matchedItems.length;

  let tableRows = '';

  if (matchedItems.length === 0) {

    tableRows = '<tr><td colspan="5" style="text-align: center; padding: 40px; color: #94a3b8;">✅ No individuals with updated disclosures at this time</td</tr>';

  } else {

    for (const item of matchedItems) {

      tableRows += `
<tr>
<td style="padding: 12px 12px; border-bottom: 1px solid #e2e8f0;"><strong>${escapeHtml(item.individualId)}</strong></td>
<td style="padding: 12px 12px; border-bottom: 1px solid #e2e8f0;">
<a href="${escapeHtml(item.url)}" style="color: #1a6d8f; text-decoration: none; font-weight: 500;" target="_blank" rel="noopener noreferrer">

              ${escapeHtml(item.individualName)}
</a>
</td>
<td style="padding: 12px 12px; border-bottom: 1px solid #e2e8f0;">${escapeHtml(item.firmId)}</td>
<td style="padding: 12px 12px; border-bottom: 1px solid #e2e8f0;">${escapeHtml(item.firmName)}</td>
<td style="padding: 12px 12px; border-bottom: 1px solid #e2e8f0; color: #64748b; font-size: 13px;">

            📅 ${escapeHtml(item.lastModifiedDate)}
</td>
</tr>

      `;

    }

  }

  return {

    changedCount: matchedItems.length,

    totalCount: totalChanged,

    tableRows: tableRows

  };

}

// Extract individual_data from input

let individualResult = { changedCount: 0, totalCount: 0, tableRows: '' };

if (items && items.length > 0) {

  const firstItem = items[0].json;

  // Check if input has individual_data array (nested structure)

  if (firstItem.individual_data && Array.isArray(firstItem.individual_data)) {

    individualResult = processIndividuals(firstItem.individual_data);

  }

  // Check if it's a flat array of individuals

  else if (firstItem.ind_source_id !== undefined) {

    individualResult = processIndividuals(items.map(i => i.json));

  }

  // If it's an array with multiple items

  else {

    const individuals = [];

    for (const item of items) {

      const json = item.json;

      if (json.ind_source_id !== undefined) {

        individuals.push(json);

      }

    }

    if (individuals.length > 0) {

      individualResult = processIndividuals(individuals);

    }

  }

}

// Return JSON for the Gmail node

return [{

  json: {

    changedCount: individualResult.changedCount,

    totalCount: individualResult.totalCount,

    tableRows: individualResult.tableRows,

    hasData: individualResult.changedCount > 0

  }

}];

// --- CUSTOMIZATION ---

